package com.ecommerce.payment.service; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*; @Entity @Table(name="payments",uniqueConstraints=@UniqueConstraint(name="uk_payment_idempotency",columnNames="idempotency_key")) public class Payment { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false) UUID orderId; @Column(nullable=false,precision=14,scale=2) BigDecimal amount; @Column(nullable=false) String idempotencyKey; @Enumerated(EnumType.STRING) Status status=Status.CAPTURED; Instant createdAt=Instant.now(); enum Status{CAPTURED,FAILED,REFUNDED} public UUID getId(){return id;} public UUID getOrderId(){return orderId;} public void setOrderId(UUID v){orderId=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public String getIdempotencyKey(){return idempotencyKey;} public void setIdempotencyKey(String v){idempotencyKey=v;} public Status getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} }